@Composable fun DeviceServerScreen(state: DeviceInteractionState, onIntent: (DeviceInteractionIntent) -> Unit) { LaunchedEffect(Unit) { onIntent(DeviceInteractionIntent.RefreshDevices) }; Column(modifier = Modifier.fillMaxSize().padding(16.dp)) { Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) { Text("设备交互 / Device Interaction", style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold); IconButton(onClick = { onIntent(DeviceInteractionIntent.RefreshDevices) }) { Icon(Icons.Default.Refresh, "Refresh") } }; Spacer(modifier = Modifier.height(16.dp)); LazyColumn(verticalArrangement = Arrangement.spacedBy(16.dp)) { item { Text("Connected Devices / 已连接设备", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Medium) }; item { if (state.connectedDevices.isEmpty()) { Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant), shape = RoundedCornerShape(12.dp)) { Box(modifier = Modifier.fillMaxWidth().padding(32.dp), contentAlignment = Alignment.Center) { Column(horizontalAlignment = Alignment.CenterHorizontally) { Icon(Icons.Default.PhoneAndroid, null, modifier = Modifier.size(48.dp), tint = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.3f)); Spacer(modifier = Modifier.height(8.dp)); Text("No devices found", color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.4f)); Spacer(modifier = Modifier.height(8.dp)); OutlinedButton(onClick = { onIntent(DeviceInteractionIntent.RefreshDevices) }) { Text("Refresh") } } } } } else { LazyRow(horizontalArrangement = Arrangement.spacedBy(12.dp)) { items(state.connectedDevices) { device -> DeviceCard(device, state.selectedDevice?.id == device.id, { onIntent(DeviceInteractionIntent.SelectDevice(device)) }) } } } }; if (state.recentScreenshots.isNotEmpty()) { item { Text("Recent Screenshots / 最近截图", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Medium) }; item { LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) { items(state.recentScreenshots) { screenshot -> ScreenshotThumbnail(screenshot, state.isLoadingScreenshot) } } } }; item { Text("Operation Panel / 操作面板", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Medium) }; item { OperationPanel(state, { onIntent(DeviceInteractionIntent.TakeScreenshot) }, { onIntent(DeviceInteractionIntent.InstallApk(it)) }, { onIntent(DeviceInteractionIntent.ReadLogcat(it)) }, { onIntent(DeviceInteractionIntent.SimulateInput(it)) }, { onIntent(DeviceInteractionIntent.ClearLog) }) }; if (state.logcatOutput.isNotEmpty()) { item { Row(modifier = Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.SpaceBetween, verticalAlignment = Alignment.CenterVertically) { Text("Logcat Output", style = MaterialTheme.typography.titleMedium, fontWeight = FontWeight.Medium); IconButton(onClick = { onIntent(DeviceInteractionIntent.ClearLog) }) { Icon(Icons.Default.Clear, "Clear") } } }; item { Card(colors = CardDefaults.cardColors(containerColor = Color(0xFF1E1E1E)), shape = RoundedCornerShape(8.dp)) { Text(state.logcatOutput, style = MaterialTheme.typography.bodySmall, fontFamily = FontFamily.Monospace, color = Color(0xFF00FF00), modifier = Modifier.padding(12.dp)) } } } } }
@Composable private fun DeviceCard(device: AndroidDevice, isSelected: Boolean, onClick: () -> Unit) { Card(modifier = Modifier.width(160.dp).clickable(onClick = onClick), colors = CardDefaults.cardColors(containerColor = if (isSelected) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceVariant), border = if (isSelected) androidx.compose.foundation.BorderStroke(2.dp, MaterialTheme.colorScheme.primary) else null, shape = RoundedCornerShape(12.dp)) { Column(modifier = Modifier.padding(12.dp), horizontalAlignment = Alignment.CenterHorizontally) { Icon(Icons.Default.Android, null, tint = if (device.isConnected) Color(0xFF4CAF50) else Color(0xFF9E9E9E), modifier = Modifier.size(40.dp)); Spacer(modifier = Modifier.height(8.dp)); Text(device.name, style = MaterialTheme.typography.bodyMedium, fontWeight = FontWeight.Medium, maxLines = 1); Text(device.model, style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant, maxLines = 1); Spacer(modifier = Modifier.height(4.dp)); Text(text = if (device.isConnected) "Connected" else "Disconnected", style = MaterialTheme.typography.labelSmall, color = if (device.isConnected) Color(0xFF4CAF50) else Color(0xFF9E9E9E)) } } }
@Composable private fun ScreenshotThumbnail(screenshot: Screenshot, isLoading: Boolean) { Box(modifier = Modifier.size(120.dp).clip(RoundedCornerShape(8.dp)).background(MaterialTheme.colorScheme.surfaceVariant).border(1.dp, MaterialTheme.colorScheme.outline.copy(alpha = 0.3f), RoundedCornerShape(8.dp)), contentAlignment = Alignment.Center) { Column(horizontalAlignment = Alignment.CenterHorizontally) { Icon(Icons.Default.Screenshot, null, modifier = Modifier.size(32.dp), tint = MaterialTheme.colorScheme.onSurfaceVariant); Spacer(modifier = Modifier.height(4.dp)); Text("${screenshot.timestamp % 100000}L", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant) }; if (isLoading) { Box(modifier = Modifier.fillMaxSize().background(Color.Black.copy(alpha = 0.5f)), contentAlignment = Alignment.Center) { CircularProgressIndicator(modifier = Modifier.size(24.dp), strokeWidth = 2.dp, color = Color.White) } } } }
@Composable private fun OperationPanel(state: DeviceInteractionState, onTakeScreenshot: () -> Unit, onInstallApk: (String) -> Unit, onReadLogcat: (String?) -> Unit, onSimulateInput: (String) -> Unit, onClearLog: () -> Unit) { var apkPath by remember { mutableStateOf("") }; var logcatFilter by remember { mutableStateOf("") }; var inputCommand by remember { mutableStateOf("") }; val hasDevice = state.selectedDevice != null; Card(colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surfaceVariant), shape = RoundedCornerShape(12.dp)) { Column(modifier = Modifier.padding(16.dp)) { OutlinedButton(onClick = onTakeScreenshot, modifier = Modifier.fillMaxWidth(), enabled = hasDevice && !state.isLoadingScreenshot) { if (state.isLoadingScreenshot) { CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp) } else Icon(Icons.Default.Screenshot, null, modifier = Modifier.size(18.dp)); Spacer(Modifier.width(8.dp)); Text("Screenshot / 截图") }; Spacer(modifier = Modifier.height(12.dp)); Row(verticalAlignment = Alignment.CenterVertically) { OutlinedTextField(value = apkPath, onValueChange = { apkPath = it }, label = { Text("APK Path") }, modifier = Modifier.weight(1f), singleLine = true, enabled = hasDevice); Spacer(modifier = Modifier.width(8.dp)); Button(onClick = { onInstallApk(apkPath) }, enabled = hasDevice && apkPath.isNotBlank() && !state.isInstalling) { if (state.isInstalling) CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.onPrimary) else Icon(Icons.Default.Upload, null) } }; Spacer(modifier = Modifier.height(12.dp)); HorizontalDivider(); Spacer(modifier = Modifier.height(12.dp)); Row(verticalAlignment = Alignment.CenterVertically) { OutlinedTextField(value = logcatFilter, onValueChange = { logcatFilter = it }, label = { Text("Logcat Filter (optional)") }, modifier = Modifier.weight(1f), singleLine = true, enabled = hasDevice); Spacer(modifier = Modifier.width(8.dp)); Button(onClick = { onReadLogcat(logcatFilter.ifBlank { null }) }, enabled = hasDevice && !state.isReadingLogcat) { if (state.isReadingLogcat) CircularProgressIndicator(modifier = Modifier.size(16.dp), strokeWidth = 2.dp, color = MaterialTheme.colorScheme.onPrimary) else Text("Read") } }; Spacer(modifier = Modifier.height(12.dp)); Row(verticalAlignment = Alignment.CenterVertically) { OutlinedTextField(value = inputCommand, onValueChange = { inputCommand = it }, label = { Text("Input Command") }, modifier = Modifier.weight(1f), singleLine = true, enabled = hasDevice); Spacer(modifier = Modifier.width(8.dp)); Button(onClick = { onSimulateInput(inputCommand) }, enabled = hasDevice && inputCommand.isNotBlank()) { Icon(Icons.Default.Input, null) } } } }
